namespace CheckoutPricing.Domain;

public static class LoyaltyDiscountPolicy
{
    public static int CalculatePayableTotal(int subtotalCents, LoyaltyTier loyaltyTier)
    {
        var baseRate = loyaltyTier switch
        {
            LoyaltyTier.Green => 5,
            LoyaltyTier.Gold => 7,
            LoyaltyTier.Platinum => 9,
            _ => throw new ArgumentOutOfRangeException(nameof(loyaltyTier), loyaltyTier, "Unknown loyalty tier."),
        };

        var bonusRate = subtotalCents >= 20_000 ? 3 : subtotalCents >= 5_000 ? 1 : 0;
        var effectiveRate = Math.Min(baseRate + bonusRate, 10);
        var discountCents = (long)subtotalCents * effectiveRate / 100;

        return checked(subtotalCents - (int)discountCents);
    }
}
CS
